#include <errno.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/onoff.h>

#define SERVICE_CONFIG_FLAGS \
	(ONOFF_FLAG_I2C_USE | \
	 ONOFF_FLAG_ERROR | \
	 ONOFF_FLAG_ONOFF | \
	 ONOFF_FLAG_TRANSITION)

#define SERVICE_REFS_MAX UINT16_MAX

static void set_service_state(struct onoff_manager *mgr,
			      uint32_t state)
{
	mgr->flags &= ~ONOFF_STATE_MASK;
	mgr->flags |= (state & ONOFF_STATE_MASK);
}

static int validate_args(const struct onoff_manager *mgr,
			 struct onoff_client *cli)
{
	if ((mgr == NULL) || (cli == NULL)) {
		return -EINVAL;
	}

	int rv = sys_notify_validate(&cli->notify);

	if (rv == 0) {
		rv = cli->notify.flags;
		if ((rv & ~ONOFF_CLIENT_EXTENSION_POS) != rv) {
			rv = -EINVAL;
		} else {
			rv = 0;
		}
	}

	return rv;
}

int onoff_manager_init(struct onoff_manager *mgr,
		       const struct onoff_transitions *transitions)
{
	if ((mgr == NULL)
	    || (transitions == NULL)
	    || (transitions->start == NULL)
	    || (transitions->stop == NULL)) {
		return -EINVAL;
	}

	*mgr = (struct onoff_manager)ONOFF_MANAGER_INITIALIZER(transitions);

	return 0;
}

static void notify_one(struct onoff_manager *mgr,
		       struct onoff_client *cli,
		       int res)
{
	onoff_client_callback cb = (onoff_client_callback)sys_notify_finalize(&cli->notify, res);

	if (cb) {
		cb(mgr, cli, mgr->flags & ONOFF_STATE_MASK, res);
	}
}

static void notify_all(struct onoff_manager *mgr,
		       sys_slist_t *list,
		       int res)
{
	while (!sys_slist_is_empty(list)) {
		 sys_snode_t *node = sys_slist_get_not_empty(list);
		 struct onoff_client *cli =
			 CONTAINER_OF(node,
				      struct onoff_client,
				      node);

		 notify_one(mgr, cli, res);
	}
}

static void onoff_start_notify(struct onoff_manager *mgr,
			       int res)
{
	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	sys_slist_t clients = mgr->clients;
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	/* Can't have settled a start that wasn't in progress. */
	__ASSERT_NO_MSG(state == ONOFF_STATE_TO_ON);

	sys_slist_init(&mgr->clients);

	if (res < 0) {
		set_service_state(mgr, ONOFF_STATE_ERROR);
		mgr->refs = 0U;
	} else if (mgr->refs == 0U) {
		/* Held a reference during transition, now none left,
		 * so transition to off.  Don't notify anybody of the
		 * transition completion here; the client that
		 * requested the start was already notified (on a
		 * cancel) or isn't expecting one (on a release).
		 */
		set_service_state(mgr, ONOFF_STATE_TO_OFF);
		k_spin_unlock(&mgr->lock, key);
		mgr->transitions->stop(mgr, onoff_stop_notify);
		return;
	} else {
		set_service_state(mgr, ONOFF_STATE_ON);
	}

	k_spin_unlock(&mgr->lock, key);

	notify_all(mgr, &clients, res);
}

static void onoff_stop_notify(struct onoff_manager *mgr,
			      int res)
{
	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	bool notify_clients = true;
	sys_slist_t clients = mgr->clients;
	struct onoff_monitor *mon;
	struct onoff_monitor *tmp;
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	/* Can't have settled a stop that wasn't in progress. */
	__ASSERT_NO_MSG(state == ONOFF_STATE_TO_OFF);

	sys_slist_init(&mgr->clients);

	if (res < 0) {
		set_service_state(mgr, ONOFF_STATE_ERROR);
		mgr->refs = 0U;
	} else if (mgr->refs > 0U) {
		/* Lost the last reference during transition, then
		 * got a new one before the transition completed.  Now
		 * have to go back to on.
		 */
		notify_clients = false;
		mgr->clients = clients;
		set_service_state(mgr, ONOFF_STATE_TO_ON);
	} else {
		set_service_state(mgr, ONOFF_STATE_OFF);
	}

	state = mgr->flags & ONOFF_STATE_MASK;

	SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&mgr->monitors, mon, tmp, node) {
		mon->callback(mgr, mon, state, res);
	}

	k_spin_unlock(&mgr->lock, key);

	if (notify_clients) {
		notify_all(mgr, &clients, res);
	} else {
		mgr->transitions->start(mgr, onoff_start_notify);
	}
}

static void onoff_reset_notify(struct onoff_manager *mgr,
			       int res)
{
	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	sys_slist_t clients = mgr->clients;
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	/* Can't have settled a reset that wasn't in progress. */
	__ASSERT_NO_MSG(state == ONOFF_STATE_RESETTING);

	sys_slist_init(&mgr->clients);

	if (res < 0) {
		set_service_state(mgr, ONOFF_STATE_ERROR);
	} else {
		__ASSERT_NO_MSG(mgr->refs == 0U);
		set_service_state(mgr, ONOFF_STATE_OFF);
	}

	k_spin_unlock(&mgr->lock, key);

	notify_all(mgr, &clients, res);
}

int onoff_request(struct onoff_manager *mgr,
		  struct onoff_client *cli)
{
	bool add_client = false;
	bool start = false;
	bool notify = false;
	int rv = validate_args(mgr, cli);

	if (rv < 0) {
		return rv;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	switch (state) {
	case ONOFF_STATE_ON:
		if (mgr->refs == SERVICE_REFS_MAX) {
			rv = -EAGAIN;
			break;
		}

		notify = true;
		mgr->refs += 1U;
		rv = ONOFF_STATE_ON;
		break;
	case ONOFF_STATE_OFF:
		start = true;
		set_service_state(mgr, ONOFF_STATE_TO_ON);
		__fallthrough;
	case ONOFF_STATE_TO_ON:
	case ONOFF_STATE_TO_OFF:
		if (mgr->refs == SERVICE_REFS_MAX) {
			rv = -EAGAIN;
			break;
		}

		add_client = true;
		mgr->refs += 1U;
		rv = state;
		break;
	case ONOFF_STATE_RESETTING:
		rv = -EBUSY;
		break;
	case ONOFF_STATE_ERROR:
		rv = -EIO;
		break;
	default:
		__ASSERT_NO_MSG(false);
		rv = -EINVAL;
		break;
	}

	if (add_client) {
		sys_slist_append(&mgr->clients, &cli->node);
	}

	k_spin_unlock(&mgr->lock, key);

	if (start) {
		__ASSERT_NO_MSG(mgr->transitions->start != NULL);
		mgr->transitions->start(mgr, onoff_start_notify);
	} else if (notify) {
		notify_one(mgr, cli, 0);
	}

	return rv;
}

int onoff_release(struct onoff_manager *mgr)
{
	bool stop = false;

	if (mgr == NULL) {
		return -EINVAL;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;
	int rv;

	switch (state) {
	case ONOFF_STATE_ON:
		mgr->refs -= 1U;
		if (mgr->refs == 0U) {
			stop = true;
			set_service_state(mgr, ONOFF_STATE_TO_OFF);
		}

		rv = ONOFF_STATE_ON;
		break;
	case ONOFF_STATE_TO_ON:
		if (mgr->refs == 0U) {
			rv = -ENONET;
			break;
		}

		if (sys_slist_is_empty(&mgr->clients)
		    || (mgr->refs > 1U)) {
			mgr->refs -= 1U;
			rv = state;
		} else {
			rv = -EBUSY;
		}
		break;
	case ONOFF_STATE_ERROR:
		rv = -EIO;
		break;
	case ONOFF_STATE_OFF:
	case ONOFF_STATE_TO_OFF:
	case ONOFF_STATE_RESETTING:
		rv = -ENONET;
		break;
	default:
		__ASSERT_NO_MSG(false);
		rv = -EINVAL;
	}

	k_spin_unlock(&mgr->lock, key);

	if (stop) {
		__ASSERT_NO_MSG(mgr->transitions->stop != NULL);
		mgr->transitions->stop(mgr, onoff_stop_notify);
	}

	return rv;
}

int onoff_cancel(struct onoff_manager *mgr,
		 struct onoff_client *cli)
{
	bool notify = false;
	int rv = validate_args(mgr, cli);

	if (rv < 0) {
		return rv;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	rv = -EALREADY;
	switch (state) {
	case ONOFF_STATE_TO_ON:
	case ONOFF_STATE_TO_OFF:
		if (sys_slist_find_and_remove(&mgr->clients, &cli->node)) {
			mgr->refs -= 1U;
			rv = state;
			notify = true;
		}
		break;
	case ONOFF_STATE_RESETTING:
		if (sys_slist_find_and_remove(&mgr->clients, &cli->node)) {
			rv = state;
			notify = true;
		}
		break;
	case ONOFF_STATE_ERROR:
	case ONOFF_STATE_OFF:
	case ONOFF_STATE_ON:
		break;
	default:
		__ASSERT_NO_MSG(false);
		rv = -EINVAL;
		break;
	}

	k_spin_unlock(&mgr->lock, key);

	if (notify) {
		notify_one(mgr, cli, -ECANCELED);
	}

	return rv;
}

int onoff_reset(struct onoff_manager *mgr,
		struct onoff_client *cli)
{
	if ((mgr != NULL)
	    && (mgr->transitions->reset == NULL)) {
		return -ENOTSUP;
	}

	bool reset = false;
	int rv = validate_args(mgr, cli);

	if (rv < 0) {
		return rv;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);
	uint32_t state = mgr->flags & ONOFF_STATE_MASK;

	if ((state & ONOFF_FLAG_ERROR) == 0U) {
		rv = -EALREADY;
	} else {
		rv = state;
		if (state == ONOFF_STATE_ERROR) {
			reset = true;
			set_service_state(mgr, ONOFF_STATE_RESETTING);
		}
		sys_slist_append(&mgr->clients, &cli->node);
	}

	k_spin_unlock(&mgr->lock, key);

	if (reset) {
		mgr->transitions->reset(mgr, onoff_reset_notify);
	}

	return rv;
}

int onoff_monitor_register(struct onoff_manager *mgr,
			   struct onoff_monitor *mon)
{
	if ((mgr == NULL)
	    || (mon == NULL)
	    || (mon->callback == NULL)) {
		return -EINVAL;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);

	sys_slist_append(&mgr->monitors, &mon->node);

	k_spin_unlock(&mgr->lock, key);

	return 0;
}

int onoff_monitor_unregister(struct onoff_manager *mgr,
			     struct onoff_monitor *mon)
{
	int rv = -EINVAL;

	if ((mgr == NULL)
	    || (mon == NULL)) {
		return rv;
	}

	k_spinlock_key_t key = k_spin_lock(&mgr->lock);

	if (sys_slist_find_and_remove(&mgr->monitors, &mon->node)) {
		rv = 0;
	}

	k_spin_unlock(&mgr->lock, key);

	return rv;
}

int onoff_sync_lock(struct onoff_sync_service *srv,
		    k_spinlock_key_t *keyp)
{
	*keyp = k_spin_lock(&srv->lock);
	if (srv->count < 0) {
		return srv->count;
	}
	return srv->count++;
}

int onoff_sync_finalize(struct onoff_sync_service *srv,
			k_spinlock_key_t key,
			struct onoff_client *cli,
			int res,
			bool on)
{
	uint32_t state = ONOFF_STATE_ON;

	/* Clear errors visible when locked.  If the caller wants an
	 * error to be left visible it should have finalized with the
	 * negative error code.
	 */
	if ((res < 0) || (srv->count < 0)) {
		srv->count = res;
		state = ONOFF_STATE_ERROR;
	} else if (!on) {
		srv->count -= 1;
		if (srv->count == 0) {
			state = ONOFF_STATE_OFF;
		}
	} else {
		/* Empty */
	}

	int rv = srv->count;

	k_spin_unlock(&srv->lock, key);

	if (cli != NULL) {
		onoff_client_callback cb =
			(onoff_client_callback)sys_notify_finalize(&cli->notify,
								   res);

		if (cb != NULL) {
			cb(NULL, cli, state, res);
		}
	}

	return rv;
}
